			Title:       strings.TrimSpace(*raw.Title),
			Description: strings.TrimSpace(*raw.Description),
		})
	}
	if explicit {
		for i, raw := range rawEntries {
			if raw.Sequence == nil {
				return nil, "changes sequence must be set for every entry or omitted for every entry"
			}
			_ = i
		}
	}
