		Environment:   strings.TrimSpace(*input.Environment),
		Version:       strings.TrimSpace(*input.Version),
		GateStatus:    gateStatus,
		RollbackPoint: strings.TrimSpace(*input.RollbackPoint),
		Changes:       entries,
